-- СГЕНЕРИРОВАНО scripts/build-course-sql.mjs из decisions.json — руками не править.
-- Идемпотентно: можно прогонять повторно после правок контента.
begin;

insert into public.courses (key, category, title, subtitle, description, icon, ui, total_days, pass_score, exam, exam_key, ord)
values ('decisions', 'thinking', 'Принятие решений', '7 дней · 12 приёмов · сертификат', 'Научись выбирать спокойно, а не наугад: 12 простых приёмов для решений — от покупки телефона до смены работы. 3–5 минут в день.', '🧭',
        '{"binary_prompt":"Взвешенно или импульсивно?","binary_honest":"✅ Взвешенно","binary_trick":"⚡ Импульсивно","reveal_cta":"💡 Что тут поможет?","flag_icon":"💡","flag_tone":"good","exam_prompt":"Какой приём здесь поможет?","signs_title":"Когда применять","counter_title":"Как сделать","cards_word":"приёмов"}'::jsonb, 7, 9, '[{"id":0,"quote":"Нурай хочет бросить курсы английского: «Сегодня так лень идти!» А через год она собирается поступать в магистратуру за рубежом.","options":["Предсмертный анализ","Правило 10/10/10","Ожидаемая ценность","Обратимо или нет"]},{"id":1,"quote":"Руслан пятый год работает в семейном бизнесе дяди без зарплаты — «за опыт» — и боится что-то менять. Друзьям он не раз советовал не работать бесплатно, а себе не может.","options":["Ожидаемая ценность","Маленький эксперимент","Предсмертный анализ","Взгляд со стороны"]},{"id":2,"quote":"Тимур спорит сам с собой: «Покупать квартиру в ипотеку или всю жизнь снимать?» Других вариантов он даже не рассматривает.","options":["Расширить выбор","Отложить на ночь","Правило 10/10/10","Предсмертный анализ"]},{"id":3,"quote":"Алия хочет взять кредит на пышную свадьбу. Она сравнивает только рестораны и не думает, что на эти же деньги можно было бы внести первый взнос за жильё.","options":["Отложить на ночь","Маленький эксперимент","Цена упущенной возможности","Взгляд со стороны"]},{"id":4,"quote":"Бекжан третий день не может выбрать тариф мобильной связи, хотя сменить его можно в любой момент в приложении.","options":["Обратимо или нет","Предсмертный анализ","Решение по ценностям","Ожидаемая ценность"]},{"id":5,"quote":"Лене нужно платье на свадьбу подруги: тёмное, до колена, до 8000. Подходящее она нашла в первом же магазине, но обошла ещё шесть — вдруг найдётся лучше.","options":["Взгляд со стороны","«Достаточно хорошо»","Расширить выбор","Отложить на ночь"]},{"id":6,"quote":"Айбек выбирает, в какой из трёх городов переехать. Он учитывает зарплаты, климат, цены на жильё и близость к родным — но всё это для него неодинаково важно.","options":["Отложить на ночь","Маленький эксперимент","Правило 10/10/10","Взвешенные «за и против»"]},{"id":7,"quote":"Нурай может взять гарантированную подработку за 5000 сомов или участвовать в конкурсе с призом 40 000, где побеждает примерно каждый десятый.","options":["Ожидаемая ценность","Расширить выбор","Взгляд со стороны","Решение по ценностям"]},{"id":8,"quote":"Дима с друзьями через неделю едет в автопутешествие по горам — три тысячи километров. План готов, все в восторге, и никто не думал, что может сорваться.","options":["«Достаточно хорошо»","Предсмертный анализ","Ожидаемая ценность","Обратимо или нет"]},{"id":9,"quote":"Руслан хочет открыть онлайн-школу шахмат и уже собирается заказать сайт за 200 000 и рекламу. Ни одного ученика у него пока не было.","options":["Правило 10/10/10","Взгляд со стороны","Маленький эксперимент","Решение по ценностям"]},{"id":10,"quote":"Айгерим вечером узнала, что её не взяли на работу мечты. В слезах она пишет рекрутеру резкое сообщение и собирается удалить резюме со всех сайтов.","options":["Ожидаемая ценность","Взвешенные «за и против»","Маленький эксперимент","Отложить на ночь"]},{"id":11,"quote":"Бекжан выбирает: остаться юристом, как хотят родители, или пойти учиться на повара, о чём мечтал с детства. Деньги и риски он уже посчитал — варианты почти равны.","options":["Предсмертный анализ","Отложить на ночь","Решение по ценностям","Ожидаемая ценность"]}]'::jsonb, '[{"answer":1,"explain":"Лень — на один вечер, а поступление — через год. Нужно посмотреть на решение не только из «сегодня»."},{"answer":3,"explain":"Руслан уже знает ответ для других. Стоит посмотреть на себя как на друга — и применить тот же совет."},{"answer":0,"explain":"Есть и другие пути: копить на первый взнос, купить поменьше, снимать ближе к работе ещё пару лет. Выбор не сводится к двум."},{"answer":2,"explain":"Настоящая цена свадьбы — ещё и первый взнос, от которого Алия откажется. Сравнивать стоит с ним."},{"answer":0,"explain":"Ошибку исправить легко и бесплатно. Обратимые решения стоит принимать быстро."},{"answer":1,"explain":"Все требования выполнены первым вариантом. Дальнейший поиск «идеала» только отнимает время."},{"answer":3,"explain":"Много факторов разной важности — повод выписать их и дать каждому вес. Тогда сравнение станет честным."},{"answer":0,"explain":"40 000 × 0,1 = 4000 в среднем — меньше гарантированных 5000. Цифры сразу показывают, что выгоднее."},{"answer":1,"explain":"Стоит представить, что поездка сорвалась, и спросить почему: поломка, перевал закрыт, нет связи. Многое можно предусмотреть заранее."},{"answer":2,"explain":"Сначала можно найти пару учеников через знакомых и провести занятия онлайн. Если спрос есть — тогда и вкладываться в сайт."},{"answer":3,"explain":"Решения на пике обиды часто приходится жалеть. До утра ничего не случится — а утром Айгерим посмотрит на всё трезво."},{"answer":2,"explain":"Когда расчёты не решают, остаётся вопрос: что важно самому Бекжану? Выбор по своим ценностям, а не «как принято»."}]'::jsonb, 4)
on conflict (key) do update set
  category = excluded.category, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description,
  icon = excluded.icon, ui = excluded.ui, total_days = excluded.total_days, pass_score = excluded.pass_score,
  exam = excluded.exam, exam_key = excluded.exam_key, ord = excluded.ord;

insert into public.course_cards (course_key, card_key, title, icon, summary, intro_day, review, ord)
values ('decisions', 'ten-ten-ten', 'Правило 10/10/10', '⏳', 'Как я буду относиться к этому решению через 10 минут, 10 месяцев и 10 лет?', 1, '[{"type":"choice","quote":"Нурай не идёт на собеседование в компанию мечты: «Вдруг собьюсь — будет стыдно». Неловкость продлится один вечер, а такой шанс бывает раз в несколько лет.","prompt":"Какой приём здесь поможет?","options":["Правило 10/10/10","Взгляд со стороны","Решать сразу, не думая"],"answer":0,"explain":"Страх «здесь и сейчас» заслоняет главное. Через 10 месяцев неловкость забудется, а упущенный шанс — вряд ли."},{"type":"binary","quote":"Не буду просить повышения: сейчас будет неловкий разговор, а это хуже всего.","trick":true,"explain":"Неловкость — на десять минут, а зарплата — на годы. Решение принято только по ближайшим ощущениям."}]'::jsonb, 1)
