insert into public.course_cards (course_key, card_key, title, icon, summary, intro_day, review, ord)
values ('decisions', 'outside-view', 'Взгляд со стороны', '🪑', 'Спроси себя: что бы я посоветовал другу в такой же ситуации?', 1, '[{"type":"choice","quote":"Тимур третий год терпит начальника, который кричит на него при всех, и всё оправдывает: «Может, я сам виноват». В своей ситуации он путается — слишком много эмоций.","prompt":"Какой приём здесь поможет?","options":["Взгляд со стороны","Правило 10/10/10","Решать сразу, не думая"],"answer":0,"explain":"Если представить, что это история друга, ответ становится очевиден: так с людьми обращаться нельзя."},{"type":"binary","quote":"Если бы подруга спросила, стоит ли отдавать последние деньги брату, который не вернул уже три долга, я бы сказала «нет». Значит, и себе скажу «нет».","trick":false,"explain":"Человек посмотрел на свою ситуацию как на чужую — и принял трезвое решение."}]'::jsonb, 2)
