values ('decisions', 'expected-value', 'Ожидаемая ценность', '🎲', 'Умножь вероятность на выигрыш — и сравни варианты в цифрах.', 4, '[{"type":"choice","quote":"Тимуру предлагают на выбор: гарантированную премию 20 000 сомов или 100 000, если команда выполнит план. План выполняют примерно в половине случаев.","prompt":"Какой приём здесь поможет?","options":["Ожидаемая ценность","Взвешенные «за и против»","Цена упущенной возможности"],"answer":0,"explain":"100 000 × 0,5 = 50 000 в среднем — больше гарантированных 20 000. Дальше вопрос в том, может ли Тимур позволить себе получить ноль."},{"type":"binary","quote":"Билет стоит 200 сомов, шанс выиграть миллион — один на десять миллионов. Вдруг повезёт — беру десять!","trick":true,"explain":"1 000 000 ÷ 10 000 000 = 0,1 сома «ценности» на билет за 200 сомов. Большой приз заслонил крошечный шанс."}]'::jsonb, 8)
