insert into public.course_cards (course_key, card_key, title, icon, summary, intro_day, review, ord)
values ('decisions', 'values', 'Решение по ценностям', '🧭', 'Спроси: какой вариант ближе к тому, что для меня по-настоящему важно?', 6, '[{"type":"choice","quote":"Нурай выбирает между высокой зарплатой с переработками до ночи и работой попроще, где она успевает забирать дочь из садика. Цифры она уже сравнила, но выбор всё равно не даётся.","prompt":"Какой приём здесь поможет?","options":["Решение по ценностям","Ожидаемая ценность","Предсмертный анализ"],"answer":0,"explain":"Когда цифры не решают, помогает вопрос: что для меня важнее — деньги сейчас или время с дочерью?"},{"type":"binary","quote":"Для меня важнее всего быть рядом с родителями. Поэтому отказываюсь от работы в другой стране, хоть там и платят больше.","trick":false,"explain":"Человек знает свои приоритеты и выбирает вариант, который им соответствует."}]'::jsonb, 12)
