delete from public.course_cards where course_key = 'decisions' and not (card_key = any(array['ten-ten-ten', 'outside-view', 'widen-options', 'opportunity-cost', 'reversible', 'good-enough', 'weighted-pros-cons', 'expected-value', 'pre-mortem', 'small-experiment', 'sleep-on-it', 'values']::text[]));

insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('decisions', 1, 'Шаг назад', 'Правило 10/10/10 и взгляд со стороны', array['ten-ten-ten', 'outside-view']::text[], '[{"type":"intro","icon":"🧭","title":"Добро пожаловать!","text":"Каждый день мы принимаем десятки решений — и часто наугад: на эмоциях, под давлением, «как получится». За 7 дней разберём 12 простых приёмов, которые помогают выбирать спокойно. Сегодня — два способа отойти на шаг назад и посмотреть на ситуацию шире."},{"type":"chat","card":"ten-ten-ten","messages":[{"name":"Лена","text":"Мне предложили выступить на конференции, но я боюсь — вдруг собьюсь и будет стыдно."},{"name":"Дима","text":"А ты прикинь: как тебе будет через 10 минут после выступления, через 10 месяцев и через 10 лет?","flag":true},{"name":"Лена","text":"Через 10 минут — трясёт. Через 10 месяцев — уже и не вспомню. А строчка в резюме останется."}],"caption":"Страх «сейчас» кажется огромным. Правило 10/10/10 растягивает взгляд во времени — и видно, что неловкость пройдёт, а польза останется."},{"type":"concept","card":"ten-ten-ten","icon":"⏳","title":"Правило 10/10/10","definition":"Прежде чем решить, представь, как будешь относиться к последствиям через 10 минут, 10 месяцев и 10 лет. Так сиюминутные эмоции перестают заслонять главное.","signs":["Страшно или неловко прямо сейчас: отказать, признаться, попросить","Манит соблазн «здесь и сейчас»: купить, сорваться, бросить","Решение повлияет на месяцы и годы, а думаешь только о сегодня"],"counter":"Задай себе три вопроса: как я буду себя чувствовать через 10 минут? Через 10 месяцев? Через 10 лет? Выбирай то, что лучше выглядит на длинной дистанции.","note":"Цифры условные: главное — посмотреть на ближнюю, среднюю и дальнюю перспективу. Для мелочей вроде выбора обеда приём не нужен."},{"type":"chat","card":"outside-view","messages":[{"name":"Айгерим","text":"Парень опять забыл про мой день рождения. Но он же устаёт на работе… Наверное, я слишком многого хочу."},{"name":"Алия","text":"Представь, что это рассказала тебе младшая сестра. Что бы ты ей посоветовала?","flag":true},{"name":"Айгерим","text":"…Сказала бы, что она заслуживает внимания и с ним надо серьёзно поговорить."}],"caption":"В своей ситуации мы тонем в эмоциях и оправданиях, а чужую видим ясно. Поэтому совет «другу» часто и есть верный ответ."},{"type":"concept","card":"outside-view","icon":"🪑","title":"Взгляд со стороны","definition":"Представь, что с таким же выбором к тебе пришёл друг. Совет ему обычно трезвее, чем решение для себя: меньше страхов и самообмана.","signs":["Ты сильно вовлечён эмоционально: отношения, семья, обиды","Ходишь по кругу и оправдываешь то, что тебе явно не подходит","Знаешь, что сказал бы другому, но себе этого не разрешаешь"],"counter":"Опиши ситуацию так, будто она про друга: «Мой друг…». Спроси, что бы ты ему посоветовал, — и примерь этот совет на себя."}]'::jsonb, '[{"type":"binary","quote":"Не скажу соседке, что её собака лает по ночам: сейчас будет неловко. Лучше уж и дальше не высыпаться.","trick":true,"explain":"Неловкий разговор — на пять минут, а недосып — на месяцы. Правило 10/10/10 показало бы это сразу."},{"type":"binary","quote":"Если бы подруга сказала, что берёт кредит на свадьбу на 300 гостей, я бы её отговорила. Значит, и сама так не сделаю.","trick":false,"explain":"Это взгляд со стороны: совет «подруге» оказался трезвым — и его применили к себе."},{"type":"choice","quote":"Бекжан хочет бросить спортзал после первой недели: «Мышцы болят, сил нет». А цель у него — за год прийти в форму.","prompt":"Какой приём здесь поможет?","options":["Взгляд со стороны","Решать сразу, не думая","Правило 10/10/10"],"answer":2,"explain":"Боль в мышцах — дело нескольких дней, а форма через год — то, чего он хочет. Нужно посмотреть дальше сегодняшнего дня."},{"type":"choice","quote":"Лена третий месяц одалживает деньги коллеге, который ни разу их не вернул, и всё его оправдывает: «У него трудный период, он же хороший». Самой ей трезво не взглянуть — слишком жалко коллегу.","prompt":"Какой приём здесь поможет?","options":["Правило 10/10/10","Взгляд со стороны","Решать сразу, не думая"],"answer":1,"explain":"Услышав такую историю от подруги, Лена сразу сказала бы: «Хватит давать в долг». Чужую ситуацию видно яснее."},{"type":"spot","prompt":"Найди реплику, где применяют приём","messages":[{"name":"Тимур","text":"Мне предложили работу в другом городе, но придётся уехать от родителей."},{"name":"Руслан","text":"Да не парься, соглашайся — потом разберёшься."},{"name":"Тимур","text":"Страшно. Но через 10 лет я буду жалеть, если даже не попробую, а тоска по дому пройдёт за несколько месяцев."},{"name":"Руслан","text":"Ну вот, сам всё понял."}],"answer":2,"explain":"Тимур смотрит на решение на разных отрезках времени — это правило 10/10/10. А совет Руслана «потом разберёшься» — решение наугад."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Как я буду смотреть на это через год?»","label":"Правило 10/10/10"},{"quote":"«Что бы я посоветовал другу?»","label":"Взгляд со стороны"},{"quote":"«Да ладно, беру — потом разберусь»","label":"Решать сразу, не думая"}]}]'::jsonb)
on conflict (course_key, day) do update set
  title = excluded.title, subtitle = excluded.subtitle, cards = excluded.cards,
  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('decisions', 2, 'Не только «да» или «нет»', 'Расширить выбор и цена упущенной возможности', array['widen-options', 'opportunity-cost']::text[], '[{"type":"intro","icon":"🔭","title":"День 2","text":"Мы часто спрашиваем себя «делать или нет?» — и не замечаем, что вариантов больше. Сегодня научимся расширять выбор и видеть, чем мы за него на самом деле платим."},{"type":"chat","card":"widen-options","messages":[{"name":"Айбек","text":"Думаю, бросать ли университет. Учёба скучная, хочу работать."},{"name":"Нурай","text":"А какие ещё есть варианты, кроме «бросить» или «терпеть»?","flag":true},{"name":"Айбек","text":"Ну… можно перевестись на заочное и работать. Или сменить специальность."}],"caption":"«Бросить или нет» — всего два варианта. Один вопрос «а что ещё?» сразу дал третий и четвёртый — и они могут оказаться лучше обоих."},{"type":"concept","card":"widen-options","icon":"🔭","title":"Расширить выбор","definition":"Когда решение звучит как «да или нет» или «это или то», остановись и найди ещё варианты. Часто лучший выбор — тот, о котором сначала не подумал.","signs":["Вопрос звучит как «делать или не делать?»","Кажется, что выбор только между двумя плохими вариантами","Обсуждаешь один вариант и решаешь лишь, брать его или нет"],"counter":"1) Спроси: «А что ещё можно сделать?» 2) Придумай хотя бы три варианта. 3) Проверь, нельзя ли совместить два — не «или», а «и»."},{"type":"chat","card":"opportunity-cost","messages":[{"name":"Дима","text":"Нашёл новый айфон в рассрочку — всего 8000 сомов в месяц на два года."},{"name":"Лена","text":"Это почти 200 000. На что ещё ты мог бы их потратить?","flag":true},{"name":"Дима","text":"Хм… на курсы английского и поездку летом. А старый телефон пока нормально работает."}],"caption":"Цена покупки — не только цифра на ценнике, но и всё, от чего ради неё откажешься. Когда это видно, выбор становится честнее."},{"type":"concept","card":"opportunity-cost","icon":"🪙","title":"Цена упущенной возможности","definition":"У каждого решения есть скрытая цена — лучшая альтернатива, от которой ты отказываешься. Деньги, время и силы, потраченные на одно, уже не пойдут на другое.","signs":["Трата «всего» на небольшую сумму в месяц","Соглашаешься на дело, которое займёт много времени","Сравниваешь покупку только с «не покупать»"],"counter":"Спроси: «Что ещё я мог бы сделать на эти деньги или это время?» Назови лучшую альтернативу и сравни с ней, а не с «ничего».","note":"Это не повод отказывать себе во всём. Смысл — сравнивать с реальной альтернативой, а не с пустотой."}]'::jsonb, '[{"type":"binary","quote":"Друг зовёт вложить деньги в его кафе. Вариантов всего два: вложиться или обидеть друга. Вкладываюсь.","trick":true,"explain":"Вариантов больше: вложить меньше, помочь советом или руками, честно объяснить отказ. Выбор сузили до двух и решили на эмоциях."},{"type":"binary","quote":"Прежде чем согласиться на вторую подработку, посчитала: она съест все вечера, а их я трачу на учёбу, которая даст больше.","trick":false,"explain":"Учтена цена упущенной возможности: подработку сравнили с лучшим способом потратить то же время."},{"type":"choice","quote":"Алия считает, что у неё всего два пути на этот отпуск: потратить его на ремонт или на поездку. Оба ей не нравятся, а других вариантов она не искала.","prompt":"Какой приём здесь поможет?","options":["Правило 10/10/10","Взгляд со стороны","Расширить выбор"],"answer":2,"explain":"Можно поехать на неделю, а неделю потратить на ремонт, нанять мастеров, отложить ремонт на осень. Вариантов больше двух."},{"type":"choice","quote":"Руслан каждые выходные помогает знакомому с переездами за символическую плату. Он не задумывается, что в эти же субботы мог бы доделать свой сайт и начать брать заказы.","prompt":"Какой приём здесь поможет?","options":["Расширить выбор","Цена упущенной возможности","Решать сразу, не думая"],"answer":1,"explain":"Настоящая цена подработки — не потраченные субботы, а несделанный сайт и будущие заказы."},{"type":"spot","prompt":"Найди реплику, где применяют приём","messages":[{"name":"Айгерим","text":"Хочу купить машину, чтобы ездить на работу."},{"name":"Бекжан","text":"Бери в кредит, чего ждать."},{"name":"Айгерим","text":"Без машины до офиса час на маршрутке, а с ней — двадцать минут."},{"name":"Алия","text":"А кроме машины какие есть варианты? Такси, каршеринг, договориться об удалёнке пару дней в неделю…"}],"answer":3,"explain":"Алия расширяет выбор: вместо «машина или маршрутка» появляются ещё три варианта. Бекжан же предлагает решить сразу."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«А что, если есть третий путь?»","label":"Расширить выбор"},{"quote":"«На что ещё ушли бы эти деньги?»","label":"Цена упущенного"},{"quote":"«Через год я об этом и не вспомню»","label":"Правило 10/10/10"}]}]'::jsonb)
on conflict (course_key, day) do update set
  title = excluded.title, subtitle = excluded.subtitle, cards = excluded.cards,
  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('decisions', 3, 'Сколько думать?', 'Обратимо или нет и «достаточно хорошо»', array['reversible', 'good-enough']::text[], '[{"type":"intro","icon":"⏱️","title":"День 3","text":"Не все решения стоят одинаковых усилий. Сегодня — два приёма, которые экономят время и нервы: понять, насколько решение серьёзное, и вовремя остановить поиски идеала."},{"type":"chat","card":"reversible","messages":[{"name":"Нурай","text":"Неделю не могу выбрать курс по рисованию — вдруг не тот?"},{"name":"Тимур","text":"А если не понравится, можно бросить?"},{"name":"Нурай","text":"Первое занятие бесплатное, дальше оплата помесячно."},{"name":"Тимур","text":"Тогда это легко отменить — запишись и посмотри. Долго думать стоит над тем, что не переиграешь.","flag":true}],"caption":"Решение, которое легко отменить, не стоит недели мучений. А вот необратимым — продаже квартиры, переезду с детьми — стоит уделить время."},{"type":"concept","card":"reversible","icon":"🚪","title":"Обратимо или нет","definition":"Сначала пойми, можно ли отменить решение. Обратимые принимай быстро и поправляй по ходу. Необратимые — не торопясь и тщательно.","signs":["Долго мучаешься над тем, что можно вернуть, отменить или поменять","Тебя торопят с тем, что потом не переиграешь","Не понимаешь, сколько сил стоит тратить на выбор"],"counter":"Спроси: «Если ошибусь, можно ли вернуть всё как было — и чего это будет стоить?» Легко — решай быстро. Трудно или невозможно — замедлись и подключи другие приёмы.","note":"Почти любое решение можно «откатить», но с разной ценой. Важно, во сколько обойдётся ошибка."},{"type":"chat","card":"good-enough","messages":[{"name":"Дима","text":"Выбираю телефон уже месяц. Прочитал 40 обзоров, сравнил 12 моделей…"},{"name":"Лена","text":"А что тебе от него нужно?"},{"name":"Дима","text":"Хорошая камера, батарея на день, до 40 000."},{"name":"Лена","text":"Тогда бери первый, который всё это умеет. Остальное — мелочи.","flag":true}],"caption":"Идеального варианта может и не быть, а поиски отнимают время и радость. Когда требования названы, первый подходящий вариант — уже хорошее решение."},{"type":"concept","card":"good-enough","icon":"✅","title":"«Достаточно хорошо»","definition":"Вместо поиска идеала заранее определи, что тебе нужно, и выбери первый вариант, который этому соответствует.","signs":["Сравниваешь десятки почти одинаковых вариантов","Подходящее уже нашёл, но ищешь «вдруг есть лучше»","После выбора всё равно сомневаешься и жалеешь"],"counter":"1) Выпиши 3–4 обязательных требования. 2) Ищи, пока не найдёшь вариант, который им соответствует. 3) Остановись и бери его.","note":"Для важных необратимых решений планку можно поднять — но и там она должна быть конкретной, а не «идеально»."}]'::jsonb, '[{"type":"binary","quote":"Риелтор торопит: «Задаток нужно внести сегодня». Ладно, перевожу все сбережения, даже не посмотрев документы.","trick":true,"explain":"Крупное и трудно обратимое решение принимается в спешке. Именно здесь нужно замедлиться и всё проверить."},{"type":"binary","quote":"Свитер можно вернуть в течение двух недель — возьму этот, а дома решу окончательно.","trick":false,"explain":"Решение обратимое, поэтому его разумно принять быстро и поправить, если что."},{"type":"choice","quote":"Бекжан ищет квартиру в аренду. Он сам решил, что ему нужно: две комнаты, до 30 000, рядом остановка. Подходящую он нашёл ещё в первый день, но смотрит уже двадцатую — вдруг попадётся лучше.","prompt":"Какой приём здесь поможет?","options":["Расширить выбор","«Достаточно хорошо»","Цена упущенной возможности"],"answer":1,"explain":"Требования названы и выполнены — пора остановиться. Поиск «ещё чуть лучше» может длиться бесконечно."},{"type":"choice","quote":"Лена хочет сделать большую татуировку на всю руку. Эскиз она впервые увидела вчера, а мастер свободен уже завтра.","prompt":"Какой приём здесь поможет?","options":["Обратимо или нет","«Достаточно хорошо»","Цена упущенной возможности"],"answer":0,"explain":"Татуировку почти невозможно отменить. Для необратимых решений спешка — плохой союзник: стоит пожить с эскизом хотя бы пару недель."},{"type":"spot","prompt":"Найди реплику, где применяют приём","messages":[{"name":"Алия","text":"Не знаю, какую пиццу заказать, сижу уже двадцать минут."},{"name":"Руслан","text":"Давай с грибами. Не понравится — в следующий раз закажем другую."},{"name":"Алия","text":"А вдруг с грибами окажется хуже, чем с курицей?"},{"name":"Руслан","text":"Это же просто ужин — переживём."}],"answer":1,"explain":"Руслан видит, что решение легко «откатить» в следующий раз, и предлагает не тратить на него силы. Обратимое — значит, быстрое."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Это можно вернуть — решу быстро»","label":"Обратимо или нет"},{"quote":"«Подходит по всем пунктам — беру»","label":"«Достаточно хорошо»"},{"quote":"«А какие ещё есть варианты?»","label":"Расширить выбор"}]}]'::jsonb)
on conflict (course_key, day) do update set
