  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('decisions', 4, 'Считаем на бумаге', 'Взвешенные «за и против» и ожидаемая ценность', array['weighted-pros-cons', 'expected-value']::text[], '[{"type":"intro","icon":"🧮","title":"День 4","text":"Когда факторов много или в игре шансы, голова путается. Сегодня — два способа разложить решение на бумаге: дать вес аргументам и посчитать, чего стоит рискнуть."},{"type":"chat","card":"weighted-pros-cons","messages":[{"name":"Бекжан","text":"Выбираю между двумя вузами. У первого плюсов больше: общежитие, красивый кампус, друзья туда поступают."},{"name":"Айгерим","text":"Распиши плюсы и поставь каждому вес от 1 до 5. Что для тебя важнее всего?","flag":true},{"name":"Бекжан","text":"Хм… сильная программа по IT — это пять баллов. А она как раз во втором."}],"caption":"Простой список считает все пункты равными. С весами один важный плюс может перевесить пять приятных мелочей."},{"type":"concept","card":"weighted-pros-cons","icon":"⚖️","title":"Взвешенные «за и против»","definition":"Выпиши плюсы и минусы каждого варианта и оцени, насколько важен каждый пункт. Сравнивай не количество пунктов, а их общий вес.","signs":["Есть несколько вариантов и много разных факторов","Голова путается, и всё кажется одинаково важным","Хочется выбрать по числу плюсов, а не по их значению"],"counter":"1) Выпиши плюсы и минусы каждого варианта. 2) Дай каждому вес от 1 до 5. 3) Сложи баллы и посмотри, что перевешивает. 4) Если итог тебе не нравится — подумай почему: это тоже подсказка."},{"type":"chat","card":"expected-value","messages":[{"name":"Руслан","text":"Можно участвовать в конкурсе стартапов: взнос 5000, приз 100 000. Участников около сорока."},{"name":"Алия","text":"Давай посчитаем. Если шанс примерно один из сорока, то приз «стоит» в среднем 100 000 ÷ 40 = 2500. Меньше взноса.","flag":true},{"name":"Руслан","text":"Значит, идти стоит, только если мой проект сильнее среднего — или ради опыта и знакомств."}],"caption":"Ожидаемая ценность — это выигрыш, умноженный на вероятность. Она помогает трезво сравнить риск с ценой — и понять, что ещё должно перевесить."},{"type":"concept","card":"expected-value","icon":"🎲","title":"Ожидаемая ценность","definition":"Умножь возможный выигрыш на его вероятность — получишь, сколько вариант «стоит» в среднем. Так рискованные варианты можно сравнить между собой и с надёжными.","signs":["Есть шанс выиграть или проиграть, и он примерно понятен","Выбор между «надёжно, но меньше» и «рискованно, но больше»","Манит большой приз, а о шансах ты не думал"],"counter":"1) Оцени вероятность успеха — хотя бы примерно. 2) Умножь её на выигрыш. 3) Сравни с ценой участия или с надёжной альтернативой.","note":"Цифры обычно приблизительные. А проигрыш, который ты не можешь себе позволить, учитывай отдельно — даже если «в среднем» всё выгодно."}]'::jsonb, '[{"type":"binary","quote":"В розыгрыше один телефон на 50 000 участников, а билет стоит 500 сомов. Возьму двадцать — так шансы точно выше!","trick":true,"explain":"Телефон за 100 000 ÷ 50 000 участников = 2 сома «ценности» на билет за 500. Двадцать билетов — двадцать раз переплатить."},{"type":"binary","quote":"Сделала таблицу: зарплата — вес 3, дорога до работы — 5, коллектив — 4. Вторая вакансия набрала больше баллов, хотя плюсов у неё меньше. Выбираю её.","trick":false,"explain":"Это взвешенный список: важные пункты весят больше, и решение опирается на общий вес, а не на число плюсов."},{"type":"choice","quote":"Нурай выбирает ноутбук из трёх моделей. У одной лучше батарея, у другой экран, у третьей цена. А ей важнее всего вес — она много ездит.","prompt":"Какой приём здесь поможет?","options":["Ожидаемая ценность","Взвешенные «за и против»","Правило 10/10/10"],"answer":1,"explain":"Факторов много, и они неравноценны. Если дать каждому вес — вес ноутбука получит пять баллов, и выбор станет понятным."},{"type":"choice","quote":"Айбеку предлагают на выбор: фиксированные 60 000 в месяц или 30 000 плюс процент с продаж. В удачный месяц выйдет 100 000, но удачный бывает примерно один из трёх.","prompt":"Какой приём здесь поможет?","options":["Взвешенные «за и против»","Цена упущенной возможности","Ожидаемая ценность"],"answer":2,"explain":"В среднем: 100 000 × ⅓ + 30 000 × ⅔ ≈ 53 000. Это меньше гарантированных 60 000 — цифры сразу проясняют выбор."},{"type":"spot","prompt":"Найди реплику, где применяют приём","messages":[{"name":"Дима","text":"Хочу на хакатон: взнос 3000, приз 50 000."},{"name":"Лена","text":"Вроде нормально, иди!"},{"name":"Дима","text":"Не знаю, а вдруг не выиграем — деньги же пропадут."},{"name":"Тимур","text":"Давай посчитаем: команд десять, вы примерно на уровне. 50 000 ÷ 10 = 5000 — больше взноса. Плюс опыт."}],"answer":3,"explain":"Тимур умножает приз на вероятность и сравнивает с ценой участия. Это ожидаемая ценность."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Важное считаю за пять, мелочи — за один»","label":"Взвешенные «за и против»"},{"quote":"«Шанс 1 из 20, приз 100 000 — в среднем 5000»","label":"Ожидаемая ценность"},{"quote":"«Подходит по всем пунктам — беру»","label":"«Достаточно хорошо»"}]}]'::jsonb)
