  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('decisions', 5, 'Проверь до прыжка', 'Предсмертный анализ и маленький эксперимент', array['pre-mortem', 'small-experiment']::text[], '[{"type":"intro","icon":"🪂","title":"День 5","text":"Большие планы часто рушатся из-за того, о чём не подумали заранее. Сегодня — как найти слабые места до старта и как проверить идею, не рискуя всем."},{"type":"chat","card":"pre-mortem","messages":[{"name":"Тимур","text":"Через месяц запускаем доставку домашней еды. Всё продумано!"},{"name":"Айбек","text":"Давай представим: прошло полгода, и проект закрылся. Почему это случилось?","flag":true},{"name":"Тимур","text":"Ну… курьеры опаздывали, еда остывала. Или клиенты попробовали раз и не вернулись."},{"name":"Айбек","text":"Вот и подумаем, как этого не допустить, — пока не поздно."}],"caption":"Вопрос «что может пойти не так?» часто не работает: мы слишком верим в план. А когда представляешь провал уже случившимся, причины находятся сами."},{"type":"concept","card":"pre-mortem","icon":"🔮","title":"Предсмертный анализ","definition":"Перед стартом представь, что план уже провалился, и придумай, почему так вышло. Найденные причины — это риски, которые можно закрыть заранее.","signs":["Запускаешь проект, бизнес или большую поездку","Все вокруг уверены, что всё пройдёт отлично","Ошибка будет стоить дорого"],"counter":"1) Скажи: «Прошёл год, и всё провалилось». 2) Выпиши 3–5 самых вероятных причин. 3) Для каждой реши, что сделать уже сейчас.","note":"Цель — не отговорить себя, а укрепить план. Если главную причину провала закрыть нечем, это тоже важный вывод."},{"type":"chat","card":"small-experiment","messages":[{"name":"Алия","text":"Хочу уйти из банка и открыть свою кондитерскую. Уже смотрю помещения!"},{"name":"Нурай","text":"А ты пробовала печь на заказ? Хотя бы пару месяцев по выходным?","flag":true},{"name":"Алия","text":"Пока нет… Надо проверить, будут ли покупать — и не надоест ли мне самой."}],"caption":"Вместо того чтобы ставить всё на одну карту, Алия может проверить идею малой ценой. Если заказы пойдут — уходить будет уже не страшно."},{"type":"concept","card":"small-experiment","icon":"🧪","title":"Маленький эксперимент","definition":"Не прыгай сразу в большое решение — сначала проверь его в малом: пробный месяц, тестовая партия, подработка по выходным.","signs":["Решение большое, а опыта мало","Не знаешь, понравится ли тебе на самом деле","Есть способ попробовать дёшево и быстро"],"counter":"1) Спроси: «Как проверить это за неделю или месяц и малой ценой?» 2) Заранее реши, какой результат будет «да», а какой — «нет». 3) Проведи пробу и решай по фактам."}]'::jsonb, '[{"type":"binary","quote":"Ни разу не ночевал в палатке, но уже купил снаряжение на 150 000 и записался в двухнедельный поход по горам.","trick":true,"explain":"Крупные траты без единой пробы. Сначала стоило сходить в поход на выходные со взятым напрокат снаряжением."},{"type":"binary","quote":"Прежде чем переводить всю компанию на новую программу, попробуем её неделю в одном отделе.","trick":false,"explain":"Маленький эксперимент: идею проверяют малой ценой, прежде чем менять всё."},{"type":"choice","quote":"Бекжан с друзьями организует свадьбу брата на 200 гостей в загородном доме. Всё распланировано, и никто не хочет «каркать» о том, что может пойти не так.","prompt":"Какой приём здесь поможет?","options":["Маленький эксперимент","Предсмертный анализ","Ожидаемая ценность"],"answer":1,"explain":"Свадьбу не «протестируешь» заранее, а ошибка обойдётся дорого. Стоит представить, что праздник сорвался, — и найти почему: погода, транспорт, еда."},{"type":"choice","quote":"Айгерим хочет съехаться с парнем, с которым встречается три месяца, и сразу расторгнуть аренду своей квартиры. Вместе они ещё ни разу не жили дольше выходных.","prompt":"Какой приём здесь поможет?","options":["Маленький эксперимент","Взвешенные «за и против»","«Достаточно хорошо»"],"answer":0,"explain":"Можно сначала пожить вместе пару недель, не отказываясь от своей квартиры. Проба покажет больше любых рассуждений."},{"type":"spot","prompt":"Найди реплику, где применяют приём","messages":[{"name":"Нурай","text":"Предлагаю сначала напечатать 50 футболок с нашим логотипом и посмотреть, разберут ли их за месяц."},{"name":"Руслан","text":"Зачем мелочиться? Давай сразу 5000 — так дешевле за штуку."},{"name":"Нурай","text":"Дешевле, если продадим. А если нет — коробки будут стоять у тебя дома."},{"name":"Руслан","text":"Ладно, убедила."}],"answer":0,"explain":"Нурай предлагает проверить спрос на маленькой партии, прежде чем рисковать большими деньгами. Это маленький эксперимент."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Представим, что всё провалилось. Почему?»","label":"Предсмертный анализ"},{"quote":"«Сначала попробую месяц по выходным»","label":"Маленький эксперимент"},{"quote":"«Скидка только сегодня — оформляю!»","label":"Решать сразу, не думая"}]}]'::jsonb)
