insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('decisions', 6, 'Слушай себя', 'Отложить на ночь и решение по ценностям', array['sleep-on-it', 'values']::text[], '[{"type":"intro","icon":"🌙","title":"День 6","text":"Последние два приёма — про чувства. Один помогает не наломать дров на эмоциях, другой — выбрать то, что важно именно тебе, а не «как принято»."},{"type":"chat","card":"sleep-on-it","messages":[{"name":"Лена","text":"Начальница при всех раскритиковала мой отчёт. Всё, пишу заявление!"},{"name":"Айгерим","text":"Понимаю, обидно. Но давай ты отправишь его завтра утром — если всё ещё захочешь?","flag":true},{"name":"Лена","text":"Утром перечитала её замечания — половина по делу. Пойду поговорю спокойно."}],"caption":"На пике эмоций кажется, что решать надо немедленно. Ночь сна возвращает трезвость — а важное решение за одну ночь никуда не денется."},{"type":"concept","card":"sleep-on-it","icon":"🌙","title":"Отложить на ночь","definition":"Если решение принимается на сильных эмоциях или под давлением «сейчас или никогда», отложи его хотя бы до утра. Хорошее предложение обычно переживёт одну ночь.","signs":["Ты зол, обижен, расстроен — или в эйфории","Тебя торопят: «только сегодня», «решай немедленно»","Хочется прямо сейчас отправить резкое сообщение или сделать крупную покупку"],"counter":"1) Скажи себе или другим: «Отвечу завтра». 2) Запиши, что хочешь сделать и почему. 3) Утром перечитай и реши на свежую голову.","note":"Это не повод откладывать бесконечно: ночь — чтобы остыть, а не чтобы уйти от решения. В по-настоящему срочных ситуациях действуй сразу."},{"type":"chat","card":"values","messages":[{"name":"Айбек","text":"Мне предлагают работу в Дубае — денег в три раза больше. Но родители уже немолодые, и рядом с ними только я."},{"name":"Нурай","text":"Что для тебя сейчас важнее всего? Не «как правильно», а именно для тебя?","flag":true},{"name":"Айбек","text":"Быть рядом с семьёй. Значит, поищу работу с ростом здесь — а к загранице, может, вернусь через пару лет."}],"caption":"Когда цифры и списки не дают ответа, помогает вопрос о ценностях. О решении, которое совпадает с тем, что для тебя важно, реже жалеешь."},{"type":"concept","card":"values","icon":"🧭","title":"Решение по ценностям","definition":"Назови 2–3 вещи, которые для тебя по-настоящему важны: семья, свобода, здоровье, развитие. И выбери вариант, который больше им соответствует.","signs":["Варианты почти равны по цифрам, но ощущаются совсем по-разному","Решаешь, «как принято», а не как хочешь сам","Выбор касается образа жизни: работа, переезд, отношения"],"counter":"1) Выпиши три свои главные ценности. 2) Для каждого варианта спроси: «Он приближает меня к ним или отдаляет?» 3) Выбери тот, что ближе.","note":"Ценности не отменяют здравый смысл: если вариант «по душе» не позволяет оплатить жизнь, ищи компромисс, а не жертву."}]'::jsonb, '[{"type":"binary","quote":"Поругался с другом и в час ночи написал ему длинное сообщение со всеми обидами за десять лет. Отправил не перечитывая.","trick":true,"explain":"Решение на пике злости, ночью, без паузы. Утром это сообщение, скорее всего, выглядело бы иначе."},{"type":"binary","quote":"Мне важнее время с детьми, чем карьерный рост. Поэтому выбираю должность без командировок, хоть она и скромнее.","trick":false,"explain":"Выбор сделан осознанно — по тому, что для человека важнее всего."},{"type":"choice","quote":"Бекжану в салоне говорят: «Кредит на мотоцикл одобряем только сегодня, завтра условия будут хуже». Он взволнован и уже достаёт паспорт.","prompt":"Какой приём здесь поможет?","options":["Решение по ценностям","Маленький эксперимент","Отложить на ночь"],"answer":2,"explain":"Давление «только сегодня» плюс сильные эмоции — главный повод взять паузу до утра."},{"type":"choice","quote":"Айгерим выбирает между стабильной работой в крупной компании, которую одобряют родители, и местом в маленькой студии дизайна, где ей по-настоящему интересно. Зарплаты почти одинаковые.","prompt":"Какой приём здесь поможет?","options":["Ожидаемая ценность","Решение по ценностям","Отложить на ночь"],"answer":1,"explain":"Цифры равны, а варианты ощущаются по-разному. Вопрос — что важно самой Айгерим, а не «как принято»."},{"type":"spot","prompt":"Найди реплику, где применяют приём","messages":[{"name":"Тимур","text":"Мне предлагают стать руководителем отдела. Зарплата выше, но программировать почти не придётся."},{"name":"Дима","text":"Конечно соглашайся — это же повышение!"},{"name":"Тимур","text":"Для меня главное — делать то, что люблю, и расти как инженер. Руководство меня от этого отдаляет."},{"name":"Дима","text":"Тогда спроси, нет ли пути старшего разработчика."}],"answer":2,"explain":"Тимур сверяет предложение со своими ценностями, а не с тем, «как принято». Это решение по ценностям."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Отвечу завтра, на свежую голову»","label":"Отложить на ночь"},{"quote":"«Что для меня по-настоящему важно?»","label":"Решение по ценностям"},{"quote":"«Прошёл год, всё провалилось — почему?»","label":"Предсмертный анализ"}]}]'::jsonb)
on conflict (course_key, day) do update set
  title = excluded.title, subtitle = excluded.subtitle, cards = excluded.cards,
  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('decisions', 7, 'Финал', 'Как сочетать приёмы + итоговый тест', '{}'::text[], '[{"type":"intro","icon":"🏁","title":"Финальный день","text":"Ты знаешь 12 приёмов. Осталось три совета, как сочетать их в жизни, короткое повторение и итоговый тест. Сдашь — получишь сертификат."},{"type":"tip","icon":"🚦","title":"Совет 1. Сначала спроси: насколько это важно?","text":"Оцени решение: обратимо ли оно и сколько стоит ошибка. Мелкое и обратимое — реши за минуту. Крупное и необратимое — доставай остальные приёмы: расширь выбор, взвесь «за и против», проведи предсмертный анализ."},{"type":"tip","icon":"🔗","title":"Совет 2. Сочетай 2–3 приёма","text":"Для большого решения хорошо работает связка: сначала расширь выбор, потом взвесь варианты, а в конце проверь себя правилом 10/10/10 или вопросом о ценностях. Всё ещё сомневаешься — проведи маленький эксперимент. На эмоциях — сначала отложи на ночь."},{"type":"tip","icon":"🍃","title":"Совет 3. Не усложняй мелочи","text":"Какой кофе взять или какой фильм посмотреть — не стоит таблиц и подсчётов: тут хватит «достаточно хорошо». Береги силы для выборов, которые меняют жизнь. И помни: даже хорошее решение может не сработать из-за случайности — оценивай, как ты решал, а не только результат."}]'::jsonb, '[]'::jsonb)
on conflict (course_key, day) do update set
  title = excluded.title, subtitle = excluded.subtitle, cards = excluded.cards,
  theory = excluded.theory, practice = excluded.practice;
delete from public.course_days where course_key = 'decisions' and not (day = any(array[1, 2, 3, 4, 5, 6, 7]));

commit;
